import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshStandardNodeMaterial, ClampToEdgeWrapping, Vector2 } from 'three/webgpu';
import { gsap } from 'gsap';
// No additional imports needed; ctx provides fontAtlas and primitives

export default function createNode(config, ctx) {
  const group = new Group();

  // Load the base texture (cached promise)
  const texturePromise = ctx.textureLoader.loadTexture('/prism-mock/home/nodes/feature-card.png');

  // Colors from spec
  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';

  // Plate dimensions
  const plateW = 1.9;
  const plateH = 1.2;
  const pitch = 1.5;
  const loopHeight = 9.0; // 6 plates * 1.5

  // Headline text
  const headline = ctx.fontAtlas.createText('Inside the atelier', {
    fontSize: 68,
    color: paper,
    align: 'left'
  });
  headline.position.set(-1.6, 1.9, 0);
  group.add(headline);

  // Store plate meshes, caption texts, frame meshes, and focused state
  const plates = [];
  const captions = [];
  const frames = [];
  const captionTexts = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  // Create six plates with frames
  for (let i = 0; i < 6; i++) {
    // Plate mesh
    const geo = new PlaneGeometry(plateW, plateH);
    const mat = new MeshStandardNodeMaterial({
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      color: '#0b0b10' // temp until texture loads
    });
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0.9, 0, 0);
    const plateGroup = new Group();
    plateGroup.add(mesh);

    // Frame (bevel)
    const frameGeo = new BoxGeometry(plateW + 0.06, plateH + 0.06, 0.03);
    const frameMat = new MeshStandardNodeMaterial({
      color: ink,
      roughness: 0.5,
      metalness: 0.5
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.set(0.9, 0, -0.015);
    plateGroup.add(frame);
    frames.push(frame);

    // Caption text
    const caption = ctx.fontAtlas.createText(captionTexts[i], {
      fontSize: 18,
      color: paper,
      align: 'left',
      letterSpacingPx: 0.08
    });
    caption.position.set(-1.6, 0, 0);
    caption.visible = false; // initially hidden, fades when focused
    plateGroup.add(caption);
    captions.push(caption);

    // Accent strip (hidden, shown on focused)
    const stripGeo = new PlaneGeometry(0.03, plateH);
    const stripMat = new MeshStandardNodeMaterial({
      color: accent,
      emissive: accent,
      emissiveIntensity: 1.4
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(0.9 - plateW / 2 - 0.015, 0, 0.01);
    strip.visible = false;
    plateGroup.add(strip);
    strip.userData = { isStrip: true };

    group.add(plateGroup);
    plates.push(plateGroup);
  }

  // Scroll offset state
  let currentOffset = 0;
  let targetOffset = 0;
  let focusedIndex = -1;
  let tween = null;

  // Reposition all plates based on offset
  function updatePositions() {
    let closestDist = Infinity;
    let closestIdx = 0;

    plates.forEach((pg, i) => {
      const baseY = (i * pitch) - (6 * pitch / 2) + pitch / 2 + currentOffset;
      let wrappedY = ((baseY + loopHeight / 2) % loopHeight) - loopHeight / 2;
      pg.position.y = wrappedY;

      // Track closest to y=0
      const dist = Math.abs(wrappedY);
      if (dist < closestDist) {
        closestDist = dist;
        closestIdx = i;
      }

      // Update caption position relative to plate
      captions[i].position.y = wrappedY;
    });

    // Focus effect
    if (closestIdx !== focusedIndex) {
      focusedIndex = closestIdx;
      plates.forEach((pg, i) => {
        const isFocused = i === focusedIndex;
        const plateScale = isFocused ? 1.06 : 1.0;
        gsap.to(pg.scale, {
          x: plateScale,
          y: plateScale,
          duration: 0.35,
          ease: 'cubic-bezier(0.215,0.61,0.355,1)',
          overwrite: 'auto'
        });
        // Caption fade
        gsap.to(captions[i], {
          opacity: isFocused ? 1 : 0,
          duration: 0.35,
          ease: 'power2.out',
          overwrite: 'auto',
          onStart: () => { captions[i].visible = true; },
          onComplete: () => { if (!isFocused) captions[i].visible = false; }
        });
        // Accent strip visibility
        pg.children.forEach(child => {
          if (child.userData && child.userData.isStrip) {
            gsap.to(child, {
              opacity: isFocused ? 1 : 0,
              duration: 0.35,
              ease: 'power2.out',
              overwrite: 'auto',
              onStart: () => { child.visible = true; },
              onComplete: () => { if (!isFocused) child.visible = false; }
            });
          }
        });
      });
    }
  }

  // Initialize positions
  updatePositions();

  // Load texture and assign distinct crops
  texturePromise.then(baseTex => {
    baseTex.wrapS = baseTex.wrapT = ClampToEdgeWrapping;
    const cropOffsets = [
      new Vector2(0, 0),
      new Vector2(0.5, 0),
      new Vector2(0, 0.5),
      new Vector2(0.5, 0.5),
      new Vector2(0.25, 0.25),
      new Vector2(0.75, 0.25)
    ];
    plates.forEach((pg, i) => {
      const tex = baseTex.clone();
      tex.repeat.set(0.5, 0.5);
      tex.offset.copy(cropOffsets[i]);
      tex.needsUpdate = true;
      pg.children[0].material.map = tex;
      pg.children[0].material.needsUpdate = true;
    });
  });

  // Scroll handler – call this from engine with delta scroll
  group.userData.handlers = {
    scroll: (delta) => {
      targetOffset += delta * 1.5;
      if (tween) tween.kill();
      tween = gsap.to({ val: currentOffset }, {
        val: targetOffset,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        onUpdate: function () {
          currentOffset = this.targets()[0].val;
          updatePositions();
        },
        onComplete: () => { tween = null; }
      });
    }
  };

  // Apply cinematic primitive: fly-through on scroll
  const flyRes = ctx.primitives['fly-through'](group, {
    depthUnits: 2.5,
    trigger: 'scroll'
  });

  // Cleanup
  group.userData.cleanup = () => {
    if (tween) tween.kill();
    if (flyRes && flyRes.cleanup) flyRes.cleanup();
    // dispose materials and geometries
    plates.forEach(pg => {
      pg.children.forEach(child => {
        if (child.isMesh) {
          child.geometry.dispose();
          if (Array.isArray(child.material)) child.material.forEach(m => m.dispose());
          else child.material.dispose();
        }
      });
    });
    headline.material?.dispose();
    captions.forEach(c => c.material?.dispose());
  };

  return group;
}
